/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
a = np.load('source_pixels.npz')['rgb']
r,g,b = a[...,0].astype(int), a[...,1].astype(int), a[...,2].astype(int)
mask = (g>140)&(r>120)&(r<240)&(b<120)&(g-r>-20)&(g-b>60)
for i in range(96):
    ys,xs = np.nonzero(mask[i])
    if len(xs): print(i, 'cx=%.2f cy=%.2f n=%d bbox=(%d,%d,%d,%d)'%(xs.mean(),ys.mean(),len(xs),xs.min(),xs.max(),ys.min(),ys.max()))
    else: print(i,'NONE')
\""
